class ListNode:
    def __init__(self, val, nxt=None):
        self.val = val
        self.next = nxt

def build(values):
    # Python list -> linked nodes, built from the tail so each node points forward.
    head = None
    for val in reversed(values):
        head = ListNode(val, head)
    return head

def to_list(head):
    # Linked nodes -> Python list, head to tail.
    values = []
    while head is not None:
        values.append(head.val)
        head = head.next
    return values

def solution(a, b):
    first = build(a)
    second = build(b)
    dummy = ListNode(0)      # placeholder in front of the merged list
    tail = dummy
    while first is not None and second is not None:
        if first.val <= second.val:      # ties take from the first list
            tail.next = first
            first = first.next
        else:
            tail.next = second
            second = second.next
        tail = tail.next
    # One list is used up; the other is already sorted, so attach it whole.
    tail.next = first if first is not None else second
    return to_list(dummy.next)

