def solution(a, b):
    # Insertion sort of every value: O((n + m)^2) in the worst case.
    out = []
    for value in a + b:
        i = len(out)
        while i > 0 and out[i - 1] > value:
            i -= 1
        out.insert(i, value)
    return out
